const void* pg_query_vnode_get_OidList(const void *vn) { return (const void*)((const VNode*)vn)->oid_list; }
const void* pg_query_vnode_get_AConst(const void *vn) { return (const void*)((const VNode*)vn)->a_const; }

// --- Top-level bridge function (heap-allocated result) ---

void* pg_query_bridge_parse_ast_direct(const char *input, int parser_options) {
	V_ParseAstResult *result = malloc(sizeof(V_ParseAstResult));
	memset(result, 0, sizeof(*result));
	PgQueryProtobufParseResult res = pg_query_parse_protobuf_opts(input, parser_options);
	if (res.error) {
		pg_query_free_protobuf_parse_result(res);
		return result;
	}
	PgQuery__ParseResult *parsed = pg_query__parse_result__unpack(NULL, res.parse_tree.len, (const uint8_t *)res.parse_tree.data);
	if (!parsed) {
		pg_query_free_protobuf_parse_result(res);
		return result;
	}
	result->version = parsed->version;
	result->stmts.len = (int)parsed->n_stmts;
	result->stmts.cap = (int)parsed->n_stmts;
	result->stmts.element_size = (int)sizeof(V_RawStmt);
	if (parsed->n_stmts > 0) {
		result->stmts.data = malloc(parsed->n_stmts * sizeof(V_RawStmt));
		for (size_t i = 0; i < parsed->n_stmts; i++) {
			V_RawStmt *rs = &((V_RawStmt *)result->stmts.data)[i];
			rs->stmt_location = parsed->stmts[i]->stmt_location;
			rs->stmt_len = parsed->stmts[i]->stmt_len;
			rs->stmt = convert_Node(parsed->stmts[i]->stmt);
		}
	}
	pg_query__parse_result__free_unpacked(parsed, NULL);
	pg_query_free_protobuf_parse_result(res);
	return result;
}

void pg_query_bridge_free_ast_result(void *ptr) {
	if (!ptr) return;
	V_ParseAstResult *result = (V_ParseAstResult*)ptr;
	if (result->stmts.data) {
		free(result->stmts.data);
	}
	free(result);
}

